import { spawnSync } from "node:child_process";
import { existsSync, readFileSync, realpathSync, writeFileSync } from "node:fs";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { checkArguments, parse, replayArguments, replayRequest, } from "./args.js";
import { ARGUMENTS_CHECKED_ENV, BRANCH_CODE_CHANGES, NO_GITHUB, REPLAY_COMMAND_ENV, WORKFLOW, } from "./constants.js";
import { api, clearGithubAccess, githubAccess, preflight, repository, } from "./github.js";
import { cleanup, reportSteps, runCli, save, stateDirectory, withExecutionLock, } from "./local.js";
import { runCommand } from "./runner.js";
import { CommandError, deps, HTTPError, URLError, ValueError, } from "./runtime.js";
import { branchPoint, codeChangeBase, sensitive, snapshot } from "./snapshot.js";
import { CloudFixture, capture, ID, RUN, stub, TRACE, withEnv, } from "./testFixture.js";
const limits = vi.hoisted(() => ({ checkArgumentsSeconds: 300 }));
vi.mock("./constants.js", async (original) => {
    const actual = await original();
    return {
        ...actual,
        get CHECK_ARGUMENTS_SECONDS() {
            return limits.checkArgumentsSeconds;
        },
    };
});
function sequence(values) {
    let index = 0;
    return () => {
        if (index >= values.length) {
            throw new Error("called more often than expected");
        }
        const value = values[index];
        index += 1;
        return value;
    };
}
function mark(fixture, name) {
    return path.join(fixture.temp, name);
}
function readMark(file) {
    return JSON.parse(readFileSync(file, "utf8"));
}
const GIT_REPORTER = `import { spawnSync } from "node:child_process"
import { writeFileSync } from "node:fs"
const git = (...args) => (spawnSync("git", args, { encoding: "utf8" }).stdout ?? "").trim()
writeFileSync(process.env.MARK, JSON.stringify({
  head: git("rev-parse", "HEAD"),
  branch: git("symbolic-ref", "--short", "-q", "HEAD"),
  changed: git("diff", "--name-only", "HEAD"),
}))
console.log(JSON.stringify({ testRunId: "${RUN}", items: [] }))
`;
const CODE_CHANGE_REPORTER = `import { readFileSync, writeFileSync } from "node:fs"
const file = process.env.BITFAB_CODE_CHANGE_PATH
const change = file ? JSON.parse(readFileSync(file, "utf8")) : null
writeFileSync(process.env.MARK, JSON.stringify({ argv: process.argv.slice(2), change }))
console.log(JSON.stringify({ testRunId: "${RUN}", items: [] }))
`;
describe("cloud replay follow-up, GitHub access, and runner", () => {
    let fixture;
    beforeEach(() => {
        fixture = new CloudFixture();
    });
    afterEach(() => {
        fixture.dispose();
        limits.checkArgumentsSeconds = 300;
    });
    function writeGitReporter() {
        fixture.write("registry.mjs", GIT_REPORTER);
        fixture.commit("reporter");
    }
    function writeCodeChangeReporter() {
        fixture.write("registry.mjs", CODE_CHANGE_REPORTER);
        fixture.commit("reporter");
    }
    function commitOnABranch() {
        const trunk = fixture.git("symbolic-ref", "--short", "HEAD");
        const trunkSha = fixture.git("rev-parse", "HEAD");
        fixture.git("checkout", "-q", "-b", "feature");
        fixture.write("tracked.txt", "committed\n");
        fixture.commit("committed experiment");
        return [trunk, trunkSha];
    }
    function snapshotOn(head, request, ...extraParents) {
        const tree = fixture.git("write-tree");
        const parents = extraParents.flatMap((sha) => ["-p", sha]);
        const commit = deps.git(fixture.root, "commit-tree", tree, "-p", head, ...parents, {
            input: `Bitfab replay ${ID}\n\n${JSON.stringify(request)}\n`,
        });
        fixture.git("checkout", "-q", "--detach", commit);
    }
    it("watch stops when GitHub never shows the dispatched run", async () => {
        const record = fixture.record({ state: "dispatch_unknown" });
        save(path.join(stateDirectory(fixture.root), `${ID}.json`), record);
        fixture.local({
            status: (current) => {
                current.state = "dispatch_unknown";
                return current;
            },
        });
        stub("monotonic", sequence([0, 60, 10 * 60]));
        const failure = runCli(["--cloud-watch", ID]);
        await expect(failure).rejects.toThrow(ValueError);
        await expect(failure).rejects.toThrow(/no run for this dispatch/);
    });
    it("watch has no limit once GitHub shows the run", async () => {
        const saved = fixture.record({ runId: 42 });
        save(path.join(stateDirectory(fixture.root), `${ID}.json`), saved);
        const states = sequence([...Array(3).fill("in_progress"), "completed"]);
        fixture.local({
            status: (current) => {
                Object.assign(current, {
                    state: states(),
                    url: "https://x",
                    conclusion: "success",
                });
                return current;
            },
            cleanup: () => { },
            reportSteps: async () => { },
            outcome: async () => ({}),
        });
        stub("monotonic", sequence([0, ...Array(10).fill(10 ** 6)]));
        const [record, found] = await runCli(["--cloud-watch", ID]);
        expect(record.state).toBe("completed");
        expect(found).toEqual({});
    });
    it("waiting reports each step as it starts", async () => {
        const record = fixture.record({ runId: 42 });
        stub("api", fixture.github(record, ""));
        const { stderr } = await capture(async () => {
            const shown = new Set();
            await reportSteps(record, shown);
            await reportSteps(record, shown);
        });
        expect(stderr).toBe("[cloud] Set up job\n[cloud] Run npm ci\n");
    });
    it("env templates allowed but not actual env files", () => {
        expect(sensitive("app/.env.example")).toBe(false);
        expect(sensitive("app/.env.production")).toBe(true);
    });
    it.skipIf(!process.env.BITFAB_CLOUD_TEST_COMMANDS)("all SDK commands with the real helper", () => {
        fixture.git("remote", "set-url", "origin", "https://github.com/acme/app.git");
        fixture.write("tracked.txt", "dirty\n");
        const beforeHead = fixture.git("rev-parse", "HEAD");
        const beforeIndex = readFileSync(path.join(fixture.root, ".git/index"));
        const commands = JSON.parse(process.env.BITFAB_CLOUD_TEST_COMMANDS ?? "{}");
        for (const [sdk, args] of Object.entries(commands)) {
            const result = spawnSync(args[0], [...args.slice(1), ...fixture.argv, "--cloud-preview"], {
                cwd: fixture.root,
                encoding: "utf8",
                timeout: 30_000,
            });
            expect(result.status, `${sdk}: ${result.stderr}`).toBe(0);
            const payload = JSON.parse(result.stdout);
            expect(payload.preview, sdk).toBe(true);
            expect(payload.changedFiles, sdk).toEqual(["tracked.txt"]);
            expect(fixture.git("rev-parse", "HEAD"), sdk).toBe(beforeHead);
            expect(readFileSync(path.join(fixture.root, ".git/index")).equals(beforeIndex), sdk).toBe(true);
        }
    });
    it("help prints once from the script", async () => {
        const [code, stdout] = await fixture.main(["--cloud", "--help"]);
        expect(code).toBe(0);
        expect(stdout).toContain("--cloud-init");
        expect(stdout).toContain("GH_TOKEN");
    });
    it("cleanup requires terminal and exact lease", () => {
        const record = fixture.record();
        const ref = `refs/heads/${record.branch}`;
        fixture.git("push", "origin", `${record.sha}:${ref}`);
        expect(() => cleanup(fixture.root, record)).toThrow(ValueError);
        expect(() => cleanup(fixture.root, record)).toThrow(/completed/);
        record.state = "completed";
        const original = record.sha;
        record.sha = "a".repeat(40);
        expect(() => cleanup(fixture.root, record)).toThrow(ValueError);
        expect(() => cleanup(fixture.root, record)).toThrow(/moved/);
        record.sha = original;
        cleanup(fixture.root, record);
        expect(record.cleaned).toBe(true);
        expect(fixture.git("ls-remote", "--heads", "origin", ref)).toBe("");
        cleanup(fixture.root, record);
    });
    it("prepared cleanup is safe without dispatch", () => {
        const record = fixture.record();
        record.state = "prepared";
        cleanup(fixture.root, record);
    });
    it("lock refuses concurrent execution", async () => {
        const directory = stateDirectory(fixture.root);
        await withExecutionLock(directory, ID, async () => {
            const second = withExecutionLock(directory, ID, () => {
                throw new Error("lock acquired twice");
            });
            await expect(second).rejects.toThrow(ValueError);
            await expect(withExecutionLock(directory, ID, () => {
                throw new Error("lock acquired twice");
            })).rejects.toThrow(/Another command/);
        });
    });
    it("lock is taken over from a holder that has exited", async () => {
        const directory = stateDirectory(fixture.root);
        const lock = path.join(directory, `${ID}.lock`);
        const exited = spawnSync(process.execPath, ["-e", "console.log(process.pid)"], {
            encoding: "utf8",
        });
        writeFileSync(lock, `${exited.stdout.trim()} Mon Jan  1 00:00:00 2026`);
        expect(await withExecutionLock(directory, ID, () => "ran")).toBe("ran");
        expect(existsSync(lock)).toBe(false);
    });
    it("lock is taken over when its process id now belongs to another process", async () => {
        const directory = stateDirectory(fixture.root);
        const lock = path.join(directory, `${ID}.lock`);
        writeFileSync(lock, `${process.ppid} Mon Jan  1 00:00:00 2001`);
        expect(await withExecutionLock(directory, ID, () => "ran")).toBe("ran");
    });
    it("lock held by a live process refuses and is left in place", async () => {
        const directory = stateDirectory(fixture.root);
        const lock = path.join(directory, `${ID}.lock`);
        const started = spawnSync("ps", ["-o", "lstart=", "-p", String(process.ppid)], {
            encoding: "utf8",
        }).stdout.trim();
        writeFileSync(lock, `${process.ppid} ${started}`);
        await expect(withExecutionLock(directory, ID, () => "ran")).rejects.toThrow(/Another command/);
        expect(readFileSync(lock, "utf8")).toBe(`${process.ppid} ${started}`);
    });
    it("repository rejects mismatched pushurl", () => {
        fixture.git("remote", "set-url", "origin", "git@github.com:acme/app.git");
        expect(repository(fixture.root)).toBe("acme/app");
        fixture.git("remote", "set-url", "--push", "origin", "https://github.com/other/repo.git");
        expect(() => repository(fixture.root)).toThrow(ValueError);
        expect(() => repository(fixture.root)).toThrow(/must match/);
    });
    it("GitHub access prefers gh then a token then the git credential", async () => {
        const helper = '!f() { test "$1" = get && echo username=x && echo password=stored-token; }; f';
        const isolated = {
            GH_TOKEN: "",
            GITHUB_TOKEN: "",
            GIT_CONFIG_GLOBAL: "/dev/null",
            GIT_CONFIG_NOSYSTEM: "1",
        };
        const savedWhich = deps.which;
        const savedCommand = deps.command;
        function restore() {
            deps.which = savedWhich;
            deps.command = savedCommand;
            clearGithubAccess();
        }
        await withEnv({ ...isolated, GH_TOKEN: "env-token" }, () => {
            stub("which", () => "/usr/bin/gh");
            stub("command", () => "gh-token");
            expect(githubAccess()).toEqual({
                source: "the GitHub CLI",
                token: "gh-token",
            });
        });
        restore();
        await withEnv({ ...isolated, GITHUB_TOKEN: "env-token" }, () => {
            stub("which", () => null);
            expect(githubAccess()).toEqual({
                source: "GITHUB_TOKEN",
                token: "env-token",
            });
        });
        restore();
        await withEnv({ ...isolated, GH_TOKEN: "env-token" }, () => {
            stub("which", () => "/usr/bin/gh");
            stub("command", () => {
                throw new CommandError("logged out");
            });
            expect(githubAccess().source).toBe("GH_TOKEN");
        });
        restore();
        await withEnv({
            ...isolated,
            GIT_CONFIG_COUNT: "1",
            GIT_CONFIG_KEY_0: "credential.helper",
            GIT_CONFIG_VALUE_0: helper,
        }, () => {
            stub("which", () => null);
            expect(githubAccess().token).toBe("stored-token");
        });
        restore();
        await withEnv(isolated, () => {
            stub("which", () => null);
            expect(() => githubAccess()).toThrow(ValueError);
            expect(() => githubAccess()).toThrow(/gh auth login.*GH_TOKEN.*https/);
        });
    });
    it("api explains a missing certificate store", async () => {
        stub("githubAccess", () => ({ source: "GH_TOKEN", token: "t" }));
        stub("urlopen", async () => {
            throw new URLError("certificate verify failed", true);
        });
        const failure = api("acme/app", "");
        await expect(failure).rejects.toThrow(CommandError);
        await expect(failure).rejects.toThrow(/NODE_EXTRA_CA_CERTS/);
    });
    it("api calls GitHub directly without the GitHub CLI", async () => {
        const requests = [];
        stub("githubAccess", () => ({ source: "GH_TOKEN", token: "t" }));
        stub("urlopen", async (request) => {
            requests.push(request);
            return Buffer.from('{"ok": true}');
        });
        stub("command", () => {
            throw new Error("ran gh");
        });
        expect(await api("acme/app", "actions/workflows/x/dispatches", {
            method: "POST",
            payload: { ref: "b" },
        })).toEqual({ ok: true });
        const request = requests[0];
        expect(request.url).toBe("https://api.github.com/repos/acme/app/actions/workflows/x/dispatches");
        expect(request.method).toBe("POST");
        expect(request.headers.Authorization).toBe("Bearer t");
        expect(JSON.parse(request.data ?? "")).toEqual({ ref: "b" });
        stub("urlopen", async () => {
            throw new HTTPError(404, new Headers(), Buffer.from("t"));
        });
        let caught = null;
        try {
            await api("acme/app", "actions/runs/1?per_page=100");
        }
        catch (error) {
            caught = error;
        }
        expect(caught).toBeInstanceOf(CommandError);
        expect(caught.httpStatus).toBe(404);
        expect(caught.message).toContain("GET repos/acme/app/actions/runs/1 failed (HTTP 404) using GH_TOKEN");
    });
    it("preflight names the check that failed", async () => {
        stub("githubAccess", () => ({ source: "GH_TOKEN", token: "t" }));
        function failsOn(target, status) {
            return async (_repo, suffix) => {
                if (suffix.startsWith(target)) {
                    throw new CommandError("failed", status);
                }
                if (suffix === "") {
                    return { permissions: { push: true } };
                }
                return { state: "active" };
            };
        }
        const cases = [
            [
                failsOn("actions/workflows/", 404),
                /GitHub Actions has not registered \.github\/workflows\/bitfab-replay\.yml \(HTTP 404\)/,
            ],
            [failsOn("", 404), /GH_TOKEN cannot read acme\/app \(HTTP 404\)/],
            [
                async () => ({ permissions: { push: false } }),
                /cannot push to acme\/app/,
            ],
            [
                async () => ({ state: "disabled_manually" }),
                /is disabled_manually; enable it/,
            ],
        ];
        for (const [provider, message] of cases) {
            stub("api", provider);
            const failure = preflight("acme/app", WORKFLOW);
            await expect(failure).rejects.toThrow(ValueError);
            await expect(failure).rejects.toThrow(message);
        }
        stub("api", async () => ({ state: "active" }));
        await preflight("acme/app", WORKFLOW);
        stub("githubAccess", () => {
            throw new ValueError(NO_GITHUB);
        });
        const failure = preflight("acme/app", WORKFLOW);
        await expect(failure).rejects.toThrow(ValueError);
        await expect(failure).rejects.toThrow(/gh auth login/);
    });
    it("the SDK checks the replay options before anything is uploaded", async () => {
        fixture.write("check.mjs", [
            "const args = process.argv.slice(2)",
            'if (args[0] !== "--check-arguments") {',
            "  console.error(JSON.stringify(args))",
            "  process.exit(1)",
            "}",
            'if (args.includes("--resume")) {',
            '  console.error("flag provided but not defined: -resume")',
            "  process.exit(1)",
            "}",
            "",
        ].join("\n"));
        const command = JSON.stringify([
            process.execPath,
            path.join(fixture.root, "check.mjs"),
        ]);
        await withEnv({ [REPLAY_COMMAND_ENV]: command }, async () => {
            checkArguments(fixture.replay);
            const preflightMock = vi.fn();
            fixture.local({ checkArguments, preflight: preflightMock });
            const failure = runCli([
                "--registry",
                "registry.mjs",
                "double",
                "--resume",
                RUN,
                "--cloud",
            ]);
            await expect(failure).rejects.toThrow(ValueError);
            await expect(failure).rejects.toThrow(/not defined: -resume/);
            expect(preflightMock).not.toHaveBeenCalled();
        });
        expect(parse(["--registry", "registry.mjs", "double", "--cloud"]).replay).toEqual(["--registry", "registry.mjs", "double"]);
    });
    it("an SDK that checked the options itself is not asked again", async () => {
        expect(replayArguments([...fixture.argv, "--cloud", "--cloud-env", "A=1"])).toEqual(fixture.replay);
        expect(replayArguments(["--cloud-watch", ID])).toBeNull();
        expect(replayArguments(["--cloud-include", "x"])).toBeNull();
        await withEnv({
            [REPLAY_COMMAND_ENV]: JSON.stringify(["false"]),
            [ARGUMENTS_CHECKED_ENV]: "1",
        }, () => {
            checkArguments(fixture.replay);
        });
    });
    it("a replay command that hangs while checking options gets a clear error", async () => {
        fixture.write("hangs.mjs", "setTimeout(() => {}, 30_000)\n");
        const command = JSON.stringify([
            process.execPath,
            path.join(fixture.root, "hangs.mjs"),
        ]);
        limits.checkArgumentsSeconds = 1;
        await withEnv({ [REPLAY_COMMAND_ENV]: command }, () => {
            let caught = null;
            try {
                checkArguments(fixture.replay);
            }
            catch (error) {
                caught = error;
            }
            expect(caught).toBeInstanceOf(ValueError);
            expect(caught.message).toMatch(/more than 1 seconds to check these options/);
        });
    });
    it("a process the replay leaves running is stopped with it", async () => {
        fixture.write("leaves_a_writer.mjs", [
            'import { spawn } from "node:child_process"',
            "const writer = spawn(process.execPath, [",
            '  "-e",',
            '  "let left = 2000; const tick = setInterval(() => { process.stderr.write(\\"late\\\\n\\"); left -= 1; if (left === 0) { clearInterval(tick) } }, 5)",',
            '], { stdio: ["ignore", "inherit", "inherit"] })',
            "writer.unref()",
            "console.log(JSON.stringify({ items: [] }))",
            "",
        ].join("\n"));
        const started = performance.now();
        const { value } = await capture(() => runCommand(fixture.root, [process.execPath, "leaves_a_writer.mjs"], null, {}));
        const [code, , , stopped] = value;
        expect([code, stopped]).toEqual([0, null]);
        expect((performance.now() - started) / 1000).toBeLessThan(4);
    });
    it("command errors carry the HTTP status without the output", () => {
        let caught = null;
        try {
            deps.command([
                process.execPath,
                "-e",
                "process.stderr.write('gh: Not Found (HTTP 404) token=abc'); process.exit(1)",
            ]);
        }
        catch (error) {
            caught = error;
        }
        expect(caught).toBeInstanceOf(CommandError);
        expect(caught.httpStatus).toBe(404);
        expect(caught.message).toContain("HTTP 404");
        expect(caught.message).not.toContain("token");
    });
    it("runner starts the same replay with the request arguments", async () => {
        fixture.write("web/registry.mjs", [
            'import { writeFileSync } from "node:fs"',
            "writeFileSync(process.env.MARK, JSON.stringify([process.cwd(), process.argv.slice(2)]))",
            `console.log(JSON.stringify({ testRunId: "${RUN}", items: [] }))`,
            "",
        ].join("\n"));
        fixture.commit();
        const file = mark(fixture, "argv");
        const args = [
            "double",
            "--trace-ids",
            TRACE,
            "--name",
            "run",
            "--fail-on-error",
        ];
        await fixture.execute({ ...fixture.request, cwd: "web", args }, { MARK: file });
        const [cwd, argv] = readMark(file);
        expect(realpathSync(cwd)).toBe(path.join(fixture.root, "web"));
        expect(argv).toEqual(args);
        const manual = [
            ...args,
            "--code-change=manual",
            "--code-change-file=change.md",
        ];
        await fixture.execute({ ...fixture.request, cwd: "web", args: manual }, { MARK: file });
        expect(readMark(file)[1]).toEqual(manual);
    });
    it("runner replays the snapshot as a change on the submitter's branch", async () => {
        writeGitReporter();
        const base = fixture.git("rev-parse", "HEAD");
        fixture.write("tracked.txt", "uncommitted\n");
        fixture.git("add", "tracked.txt");
        const file = mark(fixture, "git");
        const result = await fixture.execute({ ...fixture.request, branch: "feature/x" }, { MARK: file });
        expect(readMark(file)).toEqual({
            head: base,
            branch: "feature/x",
            changed: "tracked.txt",
        });
        expect(result.commitSha).not.toBe(base);
        expect(fixture.read("tracked.txt")).toBe("uncommitted\n");
    });
    it("runner without a branch in the request still replays the change", async () => {
        writeGitReporter();
        const base = fixture.git("rev-parse", "HEAD");
        const branch = fixture.git("symbolic-ref", "--short", "HEAD");
        fixture.write("tracked.txt", "uncommitted\n");
        fixture.git("add", "tracked.txt");
        const file = mark(fixture, "git");
        for (const request of [
            fixture.request,
            { ...fixture.request, branch: "bad..name" },
        ]) {
            await fixture.execute(request, { MARK: file });
            expect(readMark(file), String(request.branch)).toEqual({
                head: base,
                branch,
                changed: "tracked.txt",
            });
        }
    });
    it("runner sends the snapshot changes as the code change", async () => {
        writeCodeChangeReporter();
        fixture.write("tracked.txt", "uncommitted\n");
        fixture.write("new.txt", "new\n");
        fixture.write("binary.bin", "a\x00b");
        fixture.git("add", "-A");
        fixture.write("built.txt", "written by the runner's build step\n");
        const file = mark(fixture, "change");
        const args = [
            ...fixture.replay,
            "--name",
            "try a fix",
            "--code-change",
            "working-tree",
        ];
        await fixture.execute({ ...fixture.request, args }, { MARK: file });
        const seen = readMark(file);
        expect(seen.argv).toEqual(args);
        expect(seen.change).toEqual({
            description: "try a fix (2 files changed uncommitted (vs HEAD))",
            files: [
                { path: "new.txt", before: "", after: "new\n" },
                { path: "tracked.txt", before: "original\n", after: "uncommitted\n" },
            ],
        });
    });
    it("branch point is the parent branch or the default branch", () => {
        writeCodeChangeReporter();
        const [trunk, trunkSha] = commitOnABranch();
        expect(branchPoint(fixture.root)).toEqual({ sha: trunkSha, ref: trunk });
        const featureSha = fixture.git("rev-parse", "HEAD");
        fixture.git("checkout", "-q", "-b", "child");
        fixture.write("tracked.txt", "child\n");
        fixture.commit("child experiment");
        expect(branchPoint(fixture.root)).toEqual({
            sha: featureSha,
            ref: "feature",
        });
        fixture.git("checkout", "-q", trunk);
        expect(branchPoint(fixture.root)).toBeNull();
    });
    it("default branch with unpushed commits has no branch point", () => {
        const trunk = fixture.git("symbolic-ref", "--short", "HEAD");
        fixture.git("push", "-q", "-u", "origin", trunk);
        fixture.write("tracked.txt", "unpushed\n");
        fixture.commit("unpushed");
        expect(branchPoint(fixture.root)).toBeNull();
    });
    it("submit sends a branch base only for the branch code changes", () => {
        const [trunk, trunkSha] = commitOnABranch();
        fixture.git("checkout", "-q", "-b", "child");
        fixture.write("tracked.txt", "child\n");
        fixture.commit("child experiment");
        const featureSha = fixture.git("rev-parse", "feature");
        const cases = [
            ["last-branch", { sha: featureSha, ref: "feature" }],
            ["default-branch", { sha: trunkSha, ref: trunk }],
            ["working-tree", null],
            ["skip", null],
            ["manual", null],
        ];
        for (const [kind, expected] of cases) {
            expect(codeChangeBase(fixture.root, [
                ...fixture.replay,
                "--code-change",
                kind,
            ]), kind).toEqual(expected);
        }
        expect(codeChangeBase(fixture.root, fixture.replay)).toBeNull();
    });
    it("ref base is where HEAD split from the named branch or commit", () => {
        const [trunk, trunkSha] = commitOnABranch();
        const featureSha = fixture.git("rev-parse", "HEAD");
        fixture.git("checkout", "-q", trunk);
        fixture.write("tracked.txt", "trunk moved on\n");
        fixture.commit("trunk moved on");
        fixture.git("checkout", "-q", "feature");
        fixture.write("tracked.txt", "more\n");
        fixture.commit("more feature work");
        const base = (value) => codeChangeBase(fixture.root, [
            ...fixture.replay,
            "--code-change",
            "ref",
            "--code-change-base",
            value,
        ]);
        expect(base(trunk)).toEqual({ sha: trunkSha, ref: trunk });
        expect(base(featureSha)).toEqual({ sha: featureSha, ref: featureSha });
        expect(base("HEAD~1")).toEqual({ sha: featureSha, ref: "HEAD~1" });
        fixture.git("push", "-q", "origin", `${trunk}:refs/heads/dev`);
        fixture.git("fetch", "-q", "origin");
        expect(base("dev")?.ref).toBe("dev");
        expect(() => base("nope")).toThrow(ValueError);
        expect(() => base("nope")).toThrow(/--code-change-base nope names no branch or commit/);
        expect(codeChangeBase(fixture.root, [...fixture.replay, "--code-change", "ref"])).toBeNull();
    });
    it("snapshot carries the branch base as a second parent", () => {
        writeCodeChangeReporter();
        const [, trunkSha] = commitOnABranch();
        const head = fixture.git("rev-parse", "HEAD");
        const parsed = parse(fixture.argv);
        const [request, files] = replayRequest(fixture.root, parsed);
        request.codeChangeBase = branchPoint(fixture.root);
        for (const edit of [null, ".bitfab/replay.json", "tracked.txt"]) {
            if (edit) {
                fixture.write(edit, "edited\n");
            }
            const result = snapshot(fixture.root, WORKFLOW, files, request);
            expect(fixture.git("log", "-1", "--format=%P", result.sha), String(edit)).toBe(`${head} ${trunkSha}`);
        }
        request.codeChangeBase = { sha: head, ref: "feature" };
        const result = snapshot(fixture.root, WORKFLOW, files, request);
        expect(fixture.git("log", "-1", "--format=%P", result.sha)).toBe(head);
    });
    it("runner diffs the snapshot against the branch base", async () => {
        writeCodeChangeReporter();
        const [trunk, trunkSha] = commitOnABranch();
        const head = fixture.git("rev-parse", "HEAD");
        fixture.write("tracked.txt", "uncommitted\n");
        fixture.git("add", "-A");
        for (const kind of BRANCH_CODE_CHANGES) {
            const request = {
                ...fixture.request,
                args: [...fixture.replay, "--name", "try a fix", "--code-change", kind],
                codeChangeBase: { sha: trunkSha, ref: trunk },
            };
            snapshotOn(head, request, trunkSha);
            const file = mark(fixture, "change");
            await fixture.execute(request, { snapshot: false, MARK: file });
            const seen = readMark(file);
            expect(seen.argv, kind).toEqual(request.args);
            expect(seen.change, kind).toEqual({
                description: `try a fix (1 file changed vs ${trunk})`,
                files: [
                    { path: "tracked.txt", before: "original\n", after: "uncommitted\n" },
                ],
            });
            fixture.git("checkout", "-q", "feature");
        }
    });
    it("runner diffs default branch on the default branch against the snapshot base", async () => {
        writeCodeChangeReporter();
        const trunk = fixture.git("symbolic-ref", "--short", "HEAD");
        const head = fixture.git("rev-parse", "HEAD");
        fixture.write("tracked.txt", "uncommitted\n");
        fixture.git("add", "-A");
        const request = {
            ...fixture.request,
            args: [...fixture.replay, "--code-change", "default-branch"],
            codeChangeBase: { sha: head, ref: trunk },
        };
        snapshotOn(head, request);
        const file = mark(fixture, "change");
        await fixture.execute(request, { snapshot: false, MARK: file });
        expect(readMark(file).change.files).toEqual([
            { path: "tracked.txt", before: "original\n", after: "uncommitted\n" },
        ]);
    });
});
